// Valida lo que manda el panel (lib/usuarios/avisoRol.ts): { evento: 'usuario_rol', aviso_id }.
// Solo eso: destinatario y textos se leen de la MySQL en el nodo siguiente (el webhook es publico).
const body = $json.body || {};
const id = parseInt(body.aviso_id, 10);
if (body.evento !== 'usuario_rol' || !(id > 0)) return null;
return { json: { id } };

// Arma el correo de bienvenida con la fila de "Leer aviso" (usuarios_avisos_rol + users_config).
// Ningún texto ni dirección viene del webhook (es público): todo lo guardó el panel
// (lib/usuarios/avisoRol.ts). Sin fila = ya se mandó, tiene más de un día o la persona ya no tiene ese rol.
//
// Tono formal (de usted). Diseño sobrio y sin imágenes: la marca va como texto (Outlook y Gmail
// bloquean las imágenes externas de remitentes nuevos), sin degradados ni texto oculto, enlaces cuyo
// texto es la misma dirección a la que llevan, y versión en texto plano: todo eso baja la nota de spam.
const a = $json;
if (!a || !a.id) return null;
const esCorreo = (v) => /^[^\s@<>,;()]+@[^\s@<>,;()]+\.[^\s@<>,;()]+$/.test(String(v || '').trim());
const para = String(a.email || '').trim().toLowerCase();
if (!esCorreo(para)) return null;

let grupos = [];
try { grupos = JSON.parse(a.secciones_json || '[]'); } catch (e) { grupos = []; }
if (!Array.isArray(grupos)) grupos = [];

// Valencia es OSC; Caracas, Panamá y sin sede, SUPRICOM.
const SEDES = { 9: 'Valencia', 10: 'Caracas', 7: 'Panamá' };
const sede = SEDES[Number(a.cids)] || '';
const M = Number(a.cids) === 9
  ? { marca: 'OSC', razon: 'Office Solutions Center 2004, C.A.', color: '#1746C1' }
  : { marca: 'SUPRICOM', razon: Number(a.cids) === 10 ? 'SUPRICOM CCS 21, C.A.' : Number(a.cids) === 7 ? 'SUPRICOM, S.A.' : 'SUPRICOM', color: '#0E7FD1' };
const TINTA = '#0F172A';
const TEXTO = '#334155';
const GRIS = '#64748B';
const LINEA = '#E5E7EB';
const F = "font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
// Un correo escrito como texto no se vuelve enlace en Outlook/Gmail si se corta con un span vacío.
const sinEnlace = (v) => esc(v).replace('@', '<span>@</span>').replace(/\./g, '<span>.</span>');

const url = /^https?:\/\//.test(String(a.url_panel || '')) ? String(a.url_panel).replace(/\/+$/, '') : 'https://panel.supricom.com.ve';
const dominio = url.replace(/^https?:\/\//, '');
const rol = a.rol_nombre || a.rol;
const nombre = String(a.nombre || '').trim();
const cambio = !!a.rol_anterior;
const asunto = cambio
  ? 'Actualización de su rol en el Panel SUPRICOM: ' + rol
  : 'Acceso al Panel SUPRICOM: rol ' + rol;
const titulo = cambio ? 'Actualización de su rol' : 'Bienvenido(a) al Panel SUPRICOM';
const enSede = sede ? ', en la sede ' + sede : '';

const intro = cambio
  ? 'Le informamos que su rol en el Panel SUPRICOM fue actualizado de <strong style="color:' + TINTA + '">' + esc(a.rol_anterior) + '</strong> a <strong style="color:' + TINTA + '">' + esc(rol) + '</strong>' + esc(enSede) + '. A partir de este momento, su menú mostrará las secciones que corresponden al nuevo rol.'
  : 'Le informamos que se le ha otorgado acceso al Panel SUPRICOM, la plataforma interna de gestión de la empresa, con el rol de <strong style="color:' + TINTA + '">' + esc(rol) + '</strong>' + esc(enSede) + '.';
const intro2 = 'En este correo encontrará sus datos de acceso, los pasos para ingresar y las funciones disponibles para su rol.';

const p = (html, extra) => '<p style="margin:' + (extra || '14px 0 0 0') + ';' + F + ';font-size:15px;line-height:1.65;color:' + TEXTO + '">' + html + '</p>';
const h2 = (t) => '<h2 style="margin:40px 0 0 0;' + F + ';font-size:13px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:' + TINTA + '">' + t + '</h2>' +
  '<div style="margin-top:10px;height:1px;line-height:1px;font-size:0;background:' + LINEA + '">&nbsp;</div>';

const dato = (etiqueta, valor, ultimo) =>
  '<tr><td style="padding:13px 0;' + (ultimo ? '' : 'border-bottom:1px solid ' + LINEA + ';') + F + ';font-size:13px;color:' + GRIS + ';width:130px;vertical-align:top">' + etiqueta + '</td>' +
  '<td style="padding:13px 0;' + (ultimo ? '' : 'border-bottom:1px solid ' + LINEA + ';') + F + ';font-size:14px;color:' + TINTA + ';vertical-align:top">' + valor + '</td></tr>';
const filasDatos = [
  ['Dirección', '<a href="' + esc(url) + '" style="color:' + M.color + ';text-decoration:none;font-weight:600">' + esc(dominio) + '</a>'],
  ['Rol', esc(rol)],
  ...(sede ? [['Sede', esc(sede)]] : []),
  ['Usuario', sinEnlace(para)],
  ['Contraseña', 'La misma de su cuenta de Odoo'],
];
const datos = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:4px">' +
  filasDatos.map((f, i) => dato(f[0], f[1], i === filasDatos.length - 1)).join('') + '</table>';

const PASOS = [
  'Abra <a href="' + esc(url) + '" style="color:' + M.color + ';text-decoration:none;font-weight:600">' + esc(dominio) + '</a> en su navegador (Chrome, Edge o Safari).',
  'En el campo «Correo electrónico o usuario», escriba su correo corporativo: ' + sinEnlace(para) + '.',
  'En el campo «Contraseña», escriba la misma contraseña que utiliza para ingresar a Odoo.',
  'Presione «Iniciar sesión». Verá el menú con las secciones de su rol.',
];
if (cambio) PASOS.push('Si tenía el panel abierto, cierre la sesión y vuelva a ingresar para ver el menú actualizado.');
const pasos = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:6px">' +
  PASOS.map((t, i) =>
    '<tr><td style="padding:10px 0 0 0;width:30px;vertical-align:top;' + F + ';font-size:13px;font-weight:700;color:' + M.color + '">' + (i + 1) + '.</td>' +
    '<td style="padding:10px 0 0 0;' + F + ';font-size:15px;line-height:1.6;color:' + TEXTO + '">' + t + '</td></tr>').join('') +
  '</table>';

const boton = '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:26px 0 0 0"><tr>' +
  '<td bgcolor="' + TINTA + '" style="border-radius:8px;background:' + TINTA + '">' +
  '<a href="' + esc(url) + '" style="display:inline-block;padding:12px 24px;' + F + ';font-size:14px;font-weight:600;color:#FFFFFF;text-decoration:none;border-radius:8px">Ingresar a ' + esc(dominio) + '</a>' +
  '</td></tr></table>';

const lista = grupos.map((g) =>
  '<tr><td style="padding:20px 0 4px 0;' + F + ';font-size:12px;font-weight:600;letter-spacing:.8px;text-transform:uppercase;color:' + GRIS + '">' + esc(g.area) + '</td></tr>' +
  (Array.isArray(g.secciones) ? g.secciones : []).map((s) =>
    '<tr><td style="padding:5px 0;' + F + ';font-size:14px;line-height:1.55;color:' + GRIS + '"><span style="color:' + TINTA + ';font-weight:600">' + esc(s.nombre) + '</span>: ' + esc(s.detalle) + '.</td></tr>').join('')
).join('');
const funciones = p(esc(a.resumen)) +
  (lista ? p('Su menú incluye las siguientes secciones:') + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' + lista + '</table>' : '');

const IMPORTANTE = [
  'El panel no tiene una contraseña propia. Si la olvida o desea cambiarla, hágalo desde Odoo; el cambio aplica también al panel.',
  'Su acceso es personal e intransferible. No comparta su usuario ni su contraseña.',
  'Si no puede ingresar o necesita acceso a otra sección, comuníquese con su supervisor inmediato.',
];
const importante = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:6px">' +
  IMPORTANTE.map((t) =>
    '<tr><td style="padding:10px 0 0 0;width:30px;vertical-align:top;' + F + ';font-size:15px;line-height:1.6;color:' + M.color + '">&ndash;</td>' +
    '<td style="padding:10px 0 0 0;' + F + ';font-size:15px;line-height:1.6;color:' + TEXTO + '">' + t + '</td></tr>').join('') +
  '</table>';

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"><title>' + esc(asunto) + '</title>' +
  '<style>@media (max-width:600px){.caja{padding:32px 22px!important}}</style></head>' +
  '<body style="margin:0;padding:0;background:#F6F7F9">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F6F7F9" style="background:#F6F7F9"><tr><td align="center" style="padding:32px 12px">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:600px">' +
  '<tr><td style="padding:0 4px 18px 4px;' + F + ';font-size:13px;font-weight:700;letter-spacing:3px;color:' + TINTA + '">' + M.marca +
  '<span style="color:' + M.color + '">.</span><span style="font-weight:400;letter-spacing:0;color:' + GRIS + '">&nbsp;&nbsp;Panel</span></td></tr>' +
  '<tr><td class="caja" bgcolor="#FFFFFF" style="background:#FFFFFF;border:1px solid ' + LINEA + ';border-radius:12px;padding:44px 44px 40px 44px">' +
  '<div style="width:32px;height:3px;background:' + M.color + ';border-radius:2px;line-height:3px;font-size:0">&nbsp;</div>' +
  '<h1 style="margin:22px 0 0 0;' + F + ';font-size:24px;line-height:1.3;font-weight:700;color:' + TINTA + '">' + titulo + '</h1>' +
  p('Estimado(a)' + (nombre ? ' ' + esc(nombre) : '') + ':', '24px 0 0 0') +
  p(intro) + p(intro2) +
  h2('Datos de acceso') + datos +
  h2('Cómo ingresar') + pasos + boton +
  h2('Funciones de su rol') + funciones +
  h2('Información importante') + importante +
  p('Atentamente,<br><strong style="color:' + TINTA + '">Panel SUPRICOM</strong><br><span style="color:' + GRIS + '">' + esc(M.razon) + (sede ? ' · ' + esc(sede) : '') + '</span>', '40px 0 0 0') +
  '</td></tr>' +
  '<tr><td style="padding:20px 4px 0 4px;' + F + ';font-size:12px;line-height:1.6;color:#94A3B8">' +
  'Este es un mensaje automático, enviado porque se le asignó un rol en el Panel SUPRICOM' + (a.asignado_por ? ' (asignado por ' + sinEnlace(a.asignado_por) + ')' : '') + '. ' +
  'Si no esperaba este acceso, informe a su supervisor.</td></tr>' +
  '</table></td></tr></table></body></html>';

// Versión en texto plano (va como parte alterna del correo).
const texto = [
  'Estimado(a)' + (nombre ? ' ' + nombre : '') + ':',
  '',
  cambio
    ? 'Le informamos que su rol en el Panel SUPRICOM fue actualizado de ' + a.rol_anterior + ' a ' + rol + enSede + '. A partir de este momento, su menú mostrará las secciones que corresponden al nuevo rol.'
    : 'Le informamos que se le ha otorgado acceso al Panel SUPRICOM, la plataforma interna de gestión de la empresa, con el rol de ' + rol + enSede + '.',
  intro2,
  '',
  'DATOS DE ACCESO',
  'Dirección: ' + url,
  'Rol: ' + rol,
  ...(sede ? ['Sede: ' + sede] : []),
  'Usuario: ' + para,
  'Contraseña: la misma de su cuenta de Odoo',
  '',
  'CÓMO INGRESAR',
  ...PASOS.map((t, i) => (i + 1) + '. ' + t.replace(/<[^>]+>/g, '')),
  '',
  'FUNCIONES DE SU ROL',
  a.resumen || '',
  ...grupos.flatMap((g) => ['', String(g.area || ''), ...(Array.isArray(g.secciones) ? g.secciones : []).map((s) => '- ' + s.nombre + ': ' + s.detalle + '.')]),
  '',
  'INFORMACIÓN IMPORTANTE',
  ...IMPORTANTE.map((t) => '- ' + t),
  '',
  'Atentamente,',
  'Panel SUPRICOM',
  M.razon + (sede ? ' · ' + sede : ''),
].join('\n');

// Mensaje MIME completo (multipart/alternative: texto + HTML) para la API de Gmail. El nodo Gmail de
// n8n solo manda HTML; un correo sin parte de texto suma puntos de spam.
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const partir = (s) => s.replace(/.{1,76}/g, (l) => l + '\r\n');
const asuntoCorto = asunto.slice(0, 200);
const limite = 'panel-' + a.id + '-' + Date.now().toString(36);
const mime = [
  'From: =?UTF-8?B?' + b64('Panel SUPRICOM') + '?= <dmedina@supricom.com.ve>',
  'To: ' + para,
  'Subject: =?UTF-8?B?' + b64(asuntoCorto) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + limite + '"',
  '',
  '--' + limite,
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(texto)),
  '--' + limite,
  'Content-Type: text/html; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(html)),
  '--' + limite + '--',
  '',
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { aviso_id: Number(a.id), para, asunto: asuntoCorto, raw } };
